import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
} from "remotion";
import { TransitionSeries, linearTiming } from "@remotion/transitions";
import { fade } from "@remotion/transitions/fade";

export const fps = 25;
export const durationInFrames = 200;

const COLORS = {
  pink: "#FF64B8",
  lightPink: "#FEF3FF",
  mutedPurple: "#9D829F",
  darkPurple: "#694D6B",
  bg: "#1B1C1D",
  accent: "#7C5CFC",
  green: "#22C55E",
  orange: "#F59E0B",
  red: "#EF4444",
  blue: "#3B82F6",
  teal: "#14B8A6",
  panelBg: "#1B1C1D",
  cardBg: "#242526",
  headerBg: "#212223",
};

const TRANSITION = 15;

// ── Scheduled Reports (left panel) ──────────────────────────────────────────

const REPORT_ROWS = [
  { color: COLORS.pink, widths: [0.7, 0.45], barColor: COLORS.pink, barVal: 0.72, freq: 3 },
  { color: COLORS.blue, widths: [0.55, 0.38], barColor: COLORS.blue, barVal: 0.55, freq: 2 },
  { color: COLORS.teal, widths: [0.62, 0.42], barColor: COLORS.teal, barVal: 0.88, freq: 4 },
  { color: COLORS.orange, widths: [0.48, 0.36], barColor: COLORS.orange, barVal: 0.41, freq: 1 },
  { color: COLORS.accent, widths: [0.65, 0.40], barColor: COLORS.accent, barVal: 0.63, freq: 3 },
];

const ClockIcon: React.FC<{ color: string; size: number }> = ({ color, size }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none">
    <circle cx="12" cy="12" r="10" stroke={color} strokeWidth={2} />
    <polyline points="12 6 12 12 16 14" stroke={color} strokeWidth={2} strokeLinecap="round" strokeLinejoin="round" />
  </svg>
);

const CalendarDots: React.FC<{ color: string; freq: number; progress: number }> = ({ color, freq, progress }) => {
  const total = 7;
  return (
    <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
      {Array.from({ length: total }).map((_, i) => {
        const active = i % Math.round(7 / freq) === 0;
        const dotProgress = Math.max(0, Math.min(1, (progress - i * 0.08) / 0.4));
        return (
          <div
            key={i}
            style={{
              width: 12,
              height: 12,
              borderRadius: "50%",
              backgroundColor: active ? color : "rgba(255,255,255,0.15)",
              transform: `scale(${dotProgress})`,
              opacity: dotProgress,
              border: active ? `2px solid ${color}` : "2px solid rgba(255,255,255,0.2)",
            }}
          />
        );
      })}
    </div>
  );
};

const ReportRow: React.FC<{ row: typeof REPORT_ROWS[number]; delay: number }> = ({ row, delay }) => {
  const frame = useCurrentFrame();
  const { fps: f } = useVideoConfig();
  const progress = spring({ frame, fps: f, delay, config: { damping: 200 } });
  const barProgress = spring({ frame, fps: f, delay: delay + 15, config: { damping: 200 } });

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        gap: 14,
        backgroundColor: COLORS.cardBg,
        borderRadius: 20,
        border: `1.5px solid rgba(255,255,255,0.10)`,
        padding: "28px 32px",
        opacity: progress,
        transform: `translateX(${interpolate(progress, [0, 1], [-60, 0])}px)`,
      }}
    >
      <div style={{ display: "flex", alignItems: "center", gap: 20 }}>
        <div
          style={{
            width: 52,
            height: 52,
            borderRadius: 14,
            backgroundColor: `${row.color}33`,
            border: `2px solid ${row.color}88`,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            flexShrink: 0,
          }}
        >
          <ClockIcon color={row.color} size={26} />
        </div>
        <div style={{ flex: 1, display: "flex", flexDirection: "column", gap: 10 }}>
          <div style={{ width: `${row.widths[0] * 100}%`, height: 14, backgroundColor: "rgba(255,255,255,0.25)", borderRadius: 7 }} />
          <div style={{ width: `${row.widths[1] * 100}%`, height: 10, backgroundColor: "rgba(255,255,255,0.12)", borderRadius: 5 }} />
        </div>
        <CalendarDots color={row.color} freq={row.freq} progress={barProgress} />
      </div>
      <div style={{ height: 8, backgroundColor: "rgba(255,255,255,0.08)", borderRadius: 4, overflow: "hidden" }}>
        <div
          style={{
            width: `${row.barVal * 100 * barProgress}%`,
            height: "100%",
            backgroundColor: row.barColor,
            borderRadius: 4,
            opacity: 0.9,
          }}
        />
      </div>
    </div>
  );
};

const Sparkline: React.FC<{ values: number[]; color: string; progress: number; height?: number }> = ({
  values, color, progress, height = 60,
}) => {
  const w = 200;
  const h = height;
  const max = Math.max(...values);
  const min = Math.min(...values);
  const pts = values.map((v, i) => {
    const x = (i / (values.length - 1)) * w;
    const y = h - ((v - min) / (max - min + 0.01)) * h;
    return `${x},${y}`;
  }).join(" ");

  const totalLength = 400;
  const offset = interpolate(progress, [0, 1], [totalLength, 0]);
  const lastY = h - ((values[values.length - 1] - min) / (max - min + 0.01)) * h;

  return (
    <svg width={w} height={h} viewBox={`0 0 ${w} ${h}`}>
      <polyline
        points={pts}
        fill="none"
        stroke={color}
        strokeWidth={3}
        strokeLinecap="round"
        strokeLinejoin="round"
        strokeDasharray={totalLength}
        strokeDashoffset={offset}
        opacity={0.95}
      />
      <circle cx={w} cy={lastY} r={5} fill={color} opacity={progress} />
    </svg>
  );
};

// ── Monitoring Dashboard (right panel) ──────────────────────────────────────

const SPARKLINES = [
  { color: COLORS.green, values: [20, 35, 28, 45, 38, 55, 50, 62, 58, 70] },
  { color: COLORS.pink, values: [60, 55, 70, 52, 65, 48, 62, 44, 58, 40] },
  { color: COLORS.blue, values: [30, 40, 35, 50, 42, 55, 48, 60, 52, 65] },
];

const STATUS_DOTS = [
  { color: COLORS.green },
  { color: COLORS.green },
  { color: COLORS.orange },
  { color: COLORS.green },
  { color: COLORS.red },
  { color: COLORS.green },
];

const GAUGE_ARCS = [
  { color: COLORS.green, val: 0.72 },
  { color: COLORS.orange, val: 0.48 },
  { color: COLORS.pink, val: 0.88 },
];

const GaugeArc: React.FC<{ color: string; val: number; progress: number; r: number; strokeW: number }> = ({
  color, val, progress, r, strokeW,
}) => {
  const circ = 2 * Math.PI * r;
  const dash = circ * val * progress;
  const gap = circ - dash;
  return (
    <circle
      cx={80}
      cy={80}
      r={r}
      fill="none"
      stroke={color}
      strokeWidth={strokeW}
      strokeDasharray={`${dash} ${gap}`}
      strokeLinecap="round"
      strokeDashoffset={circ * 0.25}
      opacity={0.9}
    />
  );
};

const MetricCard: React.FC<{
  sparkline: typeof SPARKLINES[number];
  delay: number;
}> = ({ sparkline, delay }) => {
  const frame = useCurrentFrame();
  const { fps: f } = useVideoConfig();
  const progress = spring({ frame, fps: f, delay, config: { damping: 200 } });
  const lineProgress = spring({ frame, fps: f, delay: delay + 10, config: { damping: 200 } });

  return (
    <div
      style={{
        backgroundColor: COLORS.cardBg,
        borderRadius: 20,
        border: `1.5px solid rgba(255,255,255,0.10)`,
        padding: "24px 28px",
        opacity: progress,
        transform: `translateY(${interpolate(progress, [0, 1], [40, 0])}px)`,
        display: "flex",
        flexDirection: "column",
        gap: 14,
        flex: 1,
      }}
    >
      <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
        <div style={{ width: "60%", height: 12, backgroundColor: "rgba(255,255,255,0.22)", borderRadius: 6 }} />
        <div
          style={{
            fontSize: 52,
            fontWeight: 700,
            color: sparkline.color,
            lineHeight: 1,
            fontFamily: "'Inter', sans-serif",
            letterSpacing: "-2px",
          }}
        >
          {Math.round(interpolate(lineProgress, [0, 1], [0, sparkline.values[sparkline.values.length - 1]]))}
        </div>
      </div>
      <Sparkline values={sparkline.values} color={sparkline.color} progress={lineProgress} height={52} />
    </div>
  );
};

// ── Main Scene ───────────────────────────────────────────────────────────────

const MainScene: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: f } = useVideoConfig();

  const leftPanelProgress = spring({ frame, fps: f, delay: 2, config: { damping: 200 } });
  const rightPanelProgress = spring({ frame, fps: f, delay: 8, config: { damping: 200 } });
  const headerProgress = spring({ frame, fps: f, delay: 5, config: { damping: 200 } });
  const gaugeProgress = spring({ frame, fps: f, delay: 30, config: { damping: 200 } });
  const actionStripProgress = spring({ frame, fps: f, delay: 90, config: { damping: 200 } });
  const alertStripProgress = spring({ frame, fps: f, delay: 80, config: { damping: 200 } });

  const pulseOpacity = interpolate(
    frame % 30,
    [0, 15, 30],
    [1, 0.3, 1],
    { extrapolateRight: "clamp" }
  );

  return (
    <AbsoluteFill
      style={{
        fontFamily: "'Inter', sans-serif",
        display: "flex",
        flexDirection: "row",
        alignItems: "stretch",
        padding: "100px 80px",
        gap: 60,
        background: "transparent",
      }}
    >
      {/* ── LEFT: Scheduled Reports Panel ── */}
      <div
        style={{
          flex: 1,
          display: "flex",
          flexDirection: "column",
          gap: 0,
          backgroundColor: COLORS.panelBg,
          borderRadius: 36,
          border: "1.5px solid rgba(255,255,255,0.12)",
          overflow: "hidden",
          opacity: leftPanelProgress,
          transform: `translateX(${interpolate(leftPanelProgress, [0, 1], [-80, 0])}px)`,
        }}
      >
        {/* Header bar */}
        <div
          style={{
            backgroundColor: COLORS.headerBg,
            borderBottom: "1.5px solid rgba(255,255,255,0.10)",
            padding: "32px 40px",
            display: "flex",
            alignItems: "center",
            gap: 20,
            opacity: headerProgress,
          }}
        >
          {[COLORS.red, COLORS.orange, COLORS.green].map((c, i) => (
            <div key={i} style={{ width: 18, height: 18, borderRadius: "50%", backgroundColor: c, opacity: 0.9 }} />
          ))}
          <div style={{ flex: 1 }} />
          <div style={{ display: "flex", gap: 8 }}>
            {[0, 1, 2].map((i) => (
              <div key={i} style={{
                width: 36, height: 36, borderRadius: 8,
                backgroundColor: i === 0 ? `${COLORS.pink}44` : "rgba(255,255,255,0.08)",
                border: `1.5px solid ${i === 0 ? COLORS.pink : "rgba(255,255,255,0.15)"}`,
              }} />
            ))}
          </div>
        </div>

        {/* Report rows */}
        <div style={{ display: "flex", flexDirection: "column", gap: 20, padding: "36px 40px", flex: 1 }}>
          {REPORT_ROWS.map((row, i) => (
            <ReportRow key={i} row={row} delay={15 + i * 12} />
          ))}

          {/* Bottom action strip */}
          <div
            style={{
              marginTop: "auto",
              display: "flex",
              gap: 16,
              opacity: actionStripProgress,
              transform: `translateY(${interpolate(actionStripProgress, [0, 1], [20, 0])}px)`,
            }}
          >
            {[COLORS.pink, COLORS.accent].map((c, i) => (
              <div
                key={i}
                style={{
                  flex: i === 0 ? 1 : "unset",
                  padding: "22px 36px",
                  borderRadius: 16,
                  backgroundColor: i === 0 ? `${c}33` : "rgba(255,255,255,0.07)",
                  border: `1.5px solid ${i === 0 ? c + "88" : "rgba(255,255,255,0.12)"}`,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  gap: 12,
                }}
              >
                {i === 0 ? (
                  <>
                    <div style={{ width: 16, height: 16, borderRadius: "50%", backgroundColor: COLORS.pink }} />
                    <div style={{ width: "60%", height: 12, backgroundColor: `${COLORS.pink}88`, borderRadius: 6 }} />
                  </>
                ) : (
                  <div style={{ display: "flex", gap: 6 }}>
                    {[0, 1, 2].map((j) => (
                      <div key={j} style={{ width: 8, height: 8, borderRadius: "50%", backgroundColor: "rgba(255,255,255,0.5)" }} />
                    ))}
                  </div>
                )}
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* ── RIGHT: Monitoring Dashboard Panel ── */}
      <div
        style={{
          flex: 1,
          display: "flex",
          flexDirection: "column",
          gap: 0,
          backgroundColor: COLORS.panelBg,
          borderRadius: 36,
          border: "1.5px solid rgba(255,255,255,0.12)",
          overflow: "hidden",
          opacity: rightPanelProgress,
          transform: `translateX(${interpolate(rightPanelProgress, [0, 1], [80, 0])}px)`,
        }}
      >
        {/* Header bar */}
        <div
          style={{
            backgroundColor: COLORS.headerBg,
            borderBottom: "1.5px solid rgba(255,255,255,0.10)",
            padding: "32px 40px",
            display: "flex",
            alignItems: "center",
            gap: 20,
          }}
        >
          <div
            style={{
              width: 18,
              height: 18,
              borderRadius: "50%",
              backgroundColor: COLORS.green,
              opacity: pulseOpacity,
            }}
          />
          <div style={{
            width: 32, height: 32, borderRadius: "50%",
            border: `2px solid ${COLORS.green}`,
            opacity: 1 - pulseOpacity * 0.6,
            position: "absolute",
            marginLeft: -7,
            marginTop: -7,
          }} />
          <div style={{ flex: 1 }} />
          {[COLORS.green, COLORS.orange].map((c, i) => (
            <div key={i} style={{
              width: 48, height: 24, borderRadius: 12,
              backgroundColor: `${c}33`,
              border: `1.5px solid ${c}88`,
            }} />
          ))}
        </div>

        <div style={{ display: "flex", flexDirection: "column", gap: 28, padding: "36px 40px", flex: 1 }}>
          {/* Top row: gauges + status grid */}
          <div style={{ display: "flex", gap: 28, alignItems: "flex-start" }}>
            {/* Gauge cluster */}
            <div
              style={{
                backgroundColor: COLORS.cardBg,
                borderRadius: 24,
                border: "1.5px solid rgba(255,255,255,0.10)",
                padding: "28px 32px",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
              }}
            >
              <svg width={160} height={160} viewBox="0 0 160 160">
                {[62, 46, 30].map((r, i) => (
                  <circle key={i} cx={80} cy={80} r={r} fill="none"
                    stroke="rgba(255,255,255,0.08)" strokeWidth={12} />
                ))}
                {GAUGE_ARCS.map((arc, i) => (
                  <GaugeArc key={i} color={arc.color} val={arc.val} progress={gaugeProgress} r={[62, 46, 30][i]} strokeW={12} />
                ))}
                <circle cx={80} cy={80} r={10} fill={COLORS.cardBg} opacity={gaugeProgress} />
                <circle cx={80} cy={80} r={6} fill="rgba(255,255,255,0.4)" opacity={gaugeProgress} />
              </svg>
            </div>

            {/* Status dot grid */}
            <div
              style={{
                flex: 1,
                backgroundColor: COLORS.cardBg,
                borderRadius: 24,
                border: "1.5px solid rgba(255,255,255,0.10)",
                padding: "28px 32px",
                display: "flex",
                flexDirection: "column",
                gap: 16,
              }}
            >
              <div style={{ width: "50%", height: 12, backgroundColor: "rgba(255,255,255,0.22)", borderRadius: 6 }} />
              <div style={{ display: "flex", flexWrap: "wrap", gap: 16, marginTop: 8 }}>
                {STATUS_DOTS.map((dot, i) => {
                  const dp = Math.max(0, Math.min(1, interpolate(frame, [45 + i * 5, 65 + i * 5], [0, 1], {
                    extrapolateLeft: "clamp",
                    extrapolateRight: "clamp",
                  })));
                  return (
                    <div key={i} style={{ display: "flex", alignItems: "center", gap: 12 }}>
                      <div style={{
                        width: 20, height: 20, borderRadius: "50%",
                        backgroundColor: dot.color,
                        opacity: dp,
                        transform: `scale(${dp})`,
                      }} />
                      <div style={{
                        width: 80 + (i % 3) * 20,
                        height: 10,
                        backgroundColor: "rgba(255,255,255,0.14)",
                        borderRadius: 5,
                        opacity: dp,
                      }} />
                    </div>
                  );
                })}
              </div>
              <div style={{ height: 6, backgroundColor: "rgba(255,255,255,0.06)", borderRadius: 3, overflow: "hidden", marginTop: 8 }}>
                <div style={{
                  width: `${72 * gaugeProgress}%`, height: "100%",
                  background: `linear-gradient(90deg, ${COLORS.green}, ${COLORS.teal})`,
                  borderRadius: 3,
                }} />
              </div>
            </div>
          </div>

          {/* Metric sparkline cards */}
          <div style={{ display: "flex", gap: 20 }}>
            {SPARKLINES.map((s, i) => (
              <MetricCard key={i} sparkline={s} delay={40 + i * 15} />
            ))}
          </div>

          {/* Alert / log strip */}
          <div
            style={{
              opacity: alertStripProgress,
              transform: `translateY(${interpolate(alertStripProgress, [0, 1], [20, 0])}px)`,
              display: "flex",
              flexDirection: "column",
              gap: 12,
              backgroundColor: COLORS.cardBg,
              borderRadius: 20,
              border: "1.5px solid rgba(255,255,255,0.10)",
              padding: "24px 32px",
            }}
          >
            {[
              { color: COLORS.green, w: "75%" },
              { color: COLORS.orange, w: "55%" },
              { color: COLORS.green, w: "65%" },
            ].map((row, i) => (
              <div key={i} style={{ display: "flex", alignItems: "center", gap: 16 }}>
                <div style={{ width: 10, height: 10, borderRadius: "50%", backgroundColor: row.color, flexShrink: 0 }} />
                <div style={{ height: 10, width: row.w, backgroundColor: "rgba(255,255,255,0.15)", borderRadius: 5 }} />
                <div style={{ marginLeft: "auto", width: 60, height: 10, backgroundColor: "rgba(255,255,255,0.08)", borderRadius: 5 }} />
              </div>
            ))}
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

// ── Black Screen ─────────────────────────────────────────────────────────────

const BlackScreen: React.FC = () => (
  <AbsoluteFill style={{ backgroundColor: "transparent" }} />
);

// ── Composition ───────────────────────────────────────────────────────────────

const MainComposition: React.FC = () => {
  return (
    <TransitionSeries>
      <TransitionSeries.Sequence durationInFrames={10}>
        <BlackScreen />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: 10 })}
      />
      <TransitionSeries.Sequence durationInFrames={175 + TRANSITION}>
        <MainScene />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />
      <TransitionSeries.Sequence durationInFrames={15}>
        <BlackScreen />
      </TransitionSeries.Sequence>
    </TransitionSeries>
  );
};

export default MainComposition;
